package com.rinatabu.app;
import javax.net.ssl.HttpsURLConnection;import java.net.URL;import java.io.*;import org.json.JSONObject;
public final class AppUpdates {
 public static JSONObject latest() throws Exception {HttpsURLConnection c=(HttpsURLConnection)new URL("https://api.github.com/repos/hendayan1990-svg/rinat-abu-app/releases/latest").openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","RinatAbuAndroid/0.3.0");c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("Update unavailable");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1024*1024)throw new IOException("Oversized response");}JSONObject r=new JSONObject(out.toString("UTF-8"));if(r.optBoolean("draft")||r.optBoolean("prerelease"))throw new IOException("Not published");return r;}}finally{c.disconnect();}}
 public static int versionCode(String tag){String[] p=tag.replaceFirst("^v","").split("[-+]",2)[0].split("\\.");if(p.length!=3)throw new IllegalArgumentException("Invalid version");return Integer.parseInt(p[0])*10000+Integer.parseInt(p[1])*100+Integer.parseInt(p[2]);}
}
